#!/usr/bin/env python3
"""F10 — managed Nginx TLS version switch (`xray tls`).

Preview evidence level: CONTAINER_VERIFIED (the real Go binary runs against a
real sandbox root and a real nginx 1.24 `-t`; the fixed Bash baseline is
executed function-by-function from install.sh `tls_type`; no data plane, no
systemd, no host writes, no network).

What the fixture proves:

* a Reality install generated by `xray generate` exposes the
  `$ssl_preread_protocol` map with `#TLSv1.2    1;` and passes `nginx -t`;
* `xray tls --version 1.2+` uncomments that map entry, keeps indentation, and
  `--version 1.3` comments it back; a second identical call is a no-op;
* the resulting files are byte-identical to Bash `tls_type` choice 2/1;
* a TLS install only accepts `1.3`; `1.2+` is refused because h3/quic needs
  TLS 1.3 (Bash loops on the same refusal);
* a broken nginx configuration makes the switch fail and restores the file;
* a root without metadata exits 3, a root without a managed front exits 1,
  and invalid/missing `--version` exits 2 without writes.
"""
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from fixture_support import run_fixture  # noqa: E402

CERT_DIR = Path("/tmp/f10-certs")


def sha256_bytes(data):
    return hashlib.sha256(data).hexdigest()


def write_text(path, text):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")
    return path


def extract_bash_function(text, name):
    match = re.search(rf"^{name}\(\) \{{\n.*?^\}}$", text, re.MULTILINE | re.DOTALL)
    return match.group(0) if match else None


def metadata(tls, transport):
    return {
        "schemaVersion": 1,
        "activeEngine": "xray",
        "role": "node",
        "tls": tls,
        "transport": transport,
        "runtimeConfigPath": "usr/local/etc/xray/config.json",
        "runtimeSha256": "b" * 64,
        "ownedResources": [],
        "updatedAt": "2026-01-01T00:00:00Z",
        "install": {"port": 9443, "serverNames": ["example.com"]},
        "balanceRole": "primary",
    }


def seed_root(root, tls, transport):
    root = Path(root)
    for sub in ("usr/local/nginx/sbin", "usr/local/nginx/conf", "usr/local/nginx/logs",
                "etc/idleleo/v1", "etc/idleleo/conf/nginx", "fragments"):
        (root / sub).mkdir(parents=True, exist_ok=True)
    os.symlink("/usr/sbin/nginx", root / "usr/local/nginx/sbin/nginx")
    write_text(root / ".idleleo-phase01-sandbox", "I_ACCEPT_DISPOSABLE_SANDBOX\n")
    write_text(root / "etc/idleleo/v1/metadata.json",
               json.dumps(metadata(tls, transport), indent=2) + "\n")
    return root


def rewrite_install_paths(text, root):
    root = str(root)
    return (text.replace("/etc/idleleo/conf/nginx", f"{root}/etc/idleleo/conf/nginx")
                .replace("/usr/local/nginx", f"{root}/usr/local/nginx"))


def bash_tls_script(function, nginx_conf, tls_mode, reality_nginx, choice):
    return f"""set -euo pipefail
OK=; GreenBG=; Font=; Green=; Error=; RedBG=; Warning=; YellowBG=; Red=
log_echo(){{ :; }}
gettext(){{ printf '%s' "$1"; }}
judge(){{ return 0; }}
systemctl(){{ :; }}
read_optimize(){{ local _v="$2"; printf -v "$_v" '%s' '{choice}'; }}
nginx_conf={nginx_conf}
tls_mode={tls_mode}
reality_add_nginx={reality_nginx}
nginx_systemd_file=/nonexistent/nginx.service
{function}
tls_type
"""


def run_bash_tls(function, work, nginx_conf, tls_mode, reality_nginx, choice, f):
    script = bash_tls_script(function, nginx_conf, tls_mode, reality_nginx, choice)
    path = write_text(work / "baseline-tls.sh", script)
    return subprocess.run(["bash", str(path)], cwd=str(work), env=f.env,
                          capture_output=True, text=True, timeout=60)


def main(f):
    f.need(f.bash_repo is not None,
           "F10 requires --bash-repo for the Bash tls_type baseline")
    install = f.bash_repo / "install.sh"
    f.need(install.is_file(), f"Bash baseline not found: {install}")
    f.need(shutil.which("nginx") is not None, "nginx must be installed in the container")
    f.need(Path("/usr/lib/nginx/modules/ngx_stream_module.so").is_file(),
           "nginx stream module is required for the Reality install")
    f.need(shutil.which("openssl") is not None, "openssl is required for the TLS cert")
    source = install.read_text(encoding="utf-8")
    tls_fn = extract_bash_function(source, "tls_type")
    f.need(tls_fn is not None, "tls_type not found in install.sh")

    work = f.evidence / "f10-work"
    if work.exists():
        shutil.rmtree(work, ignore_errors=True)
    work.mkdir(parents=True, exist_ok=True)
    CERT_DIR.mkdir(parents=True, exist_ok=True)
    cert = CERT_DIR / "cert.pem"
    key = CERT_DIR / "key.pem"
    openssl = subprocess.run(["openssl", "req", "-x509", "-newkey", "rsa:2048", "-nodes",
                              "-subj", "/CN=example.com", "-days", "1",
                              "-keyout", str(key), "-out", str(cert)],
                             capture_output=True, text=True, timeout=60)
    f.need(openssl.returncode == 0, f"openssl cert generation failed: {openssl.stderr[:200]}")

    observed = {"reality": {}, "tls": {}, "baseline": {}}
    compare = {}

    # ---- S1: real Reality install and TLS 1.2+ switch -------------------
    root = seed_root(work / "reality-root", "Reality", "raw")
    gen = f.run([f.go, "--root", root, "xray", "generate", "--mode", "reality-balance",
                 "--role", "primary", "--uuid", "eeeeeeee-4444-4444-8444-444444444444",
                 "--short-id", "abcd1234", "--server-names", "example.com",
                 "--out", root / "config.json", "--nginx-out", work / "reality-nginx.conf",
                 "--fragments-out", root / "fragments", "--json"])
    f.check(gen.rc == 0, "generate reality-balance rc=0", gen.text[:300])
    conf_dir = root / "etc/idleleo/conf/nginx"
    anchor_path = conf_dir / "00-xray.conf"
    anchor = rewrite_install_paths((work / "reality-nginx.conf").read_text(encoding="utf-8"), root)
    write_text(anchor_path, anchor)
    for item in (root / "fragments").iterdir():
        shutil.copy2(item, conf_dir / item.name)
    f.check("#TLSv1.2    1;" in anchor and "$ssl_preread_protocol" in anchor,
            "generated Reality anchor keeps the commented TLSv1.2 map entry", anchor[:400])
    write_text(root / "usr/local/nginx/conf/nginx.conf", f"""load_module /usr/lib/nginx/modules/ngx_stream_module.so;
pid {root}/usr/local/nginx/logs/nginx.pid;
error_log {root}/usr/local/nginx/logs/error.log;
events {{}}
include {conf_dir}/00-xray.conf;
http {{}}
""")
    nginx = root / "usr/local/nginx/sbin/nginx"
    prefix = str(root / "usr/local/nginx") + "/"
    conf = root / "usr/local/nginx/conf/nginx.conf"
    t = f.run([nginx, "-t", "-p", prefix, "-c", conf])
    f.check(t.rc == 0, "real nginx -t accepts the generated Reality install", t.text[:300])
    observed["reality"]["nginxTest"] = t.rc

    original = anchor_path.read_text(encoding="utf-8")
    tree_before = f.tree_digest(conf_dir)
    compat = f.run([f.go, "--root", root, "xray", "tls", "--version", "1.2+", "--json"])
    compat_json = f.json_of(compat, "tls 1.2+ --json") if compat.rc == 0 else None
    f.check(compat.rc == 0, "reality tls 1.2+ rc=0", compat.text[:300])
    compat_bytes = anchor_path.read_bytes() if anchor_path.is_file() else b""
    f.check(b"TLSv1.2    1;" in compat_bytes and b"#TLSv1.2    1;" not in compat_bytes,
            "1.2+ uncomments the Reality map entry", compat_bytes.decode(errors="replace")[:400])
    if compat_json:
        f.check(compat_json["mode"] == "Reality", "json mode=Reality", json.dumps(compat_json))
        f.check(compat_json["version"] == "1.2+", "json version=1.2+")
        f.check(compat_json["changed"] is True, "json changed=true")
        f.check(compat_json["file"] == str(anchor_path), "json file is the stream anchor")
        f.check(compat_json["reloaded"] is False, "sandbox root does not reload")
        f.check(any("reload skipped" in w for w in compat_json["warnings"]),
                "json warns about the skipped reload", str(compat_json["warnings"]))
    observed["reality"]["compatFileSha256"] = sha256_bytes(compat_bytes)
    observed["reality"]["compatBytes"] = len(compat_bytes)
    after_compat = f.tree_digest(conf_dir)

    again = f.run([f.go, "--root", root, "xray", "tls", "--version", "1.2+", "--json"])
    again_json = f.json_of(again, "tls repeat --json") if again.rc == 0 else None
    f.check(again.rc == 0 and again_json and again_json["changed"] is False,
            "repeating 1.2+ is a no-op", again.text[:240])
    f.check(f.tree_digest(conf_dir) == after_compat,
            "no-op repeat leaves the config tree unchanged")

    secure = f.run([f.go, "--root", root, "xray", "tls", "--version", "1.3", "--json"])
    secure_json = f.json_of(secure, "tls 1.3 --json") if secure.rc == 0 else None
    secure_bytes = anchor_path.read_bytes() if anchor_path.is_file() else b""
    f.check(secure.rc == 0 and b"#TLSv1.2    1;" in secure_bytes,
            "1.3 comments the Reality map entry back", secure.text[:240])
    if secure_json:
        f.check(secure_json["version"] == "1.3" and secure_json["changed"] is True,
                "1.3 reports changed", json.dumps(secure_json))
    f.check(secure_bytes == original.encode(), "1.3 round-trips to the generated bytes")
    observed["reality"]["secureFileSha256"] = sha256_bytes(secure_bytes)

    # ---- S2: Bash baseline, byte for byte -------------------------------
    bash_compat_dir = work / "bash-compat"
    bash_compat_dir.mkdir()
    bash_compat = bash_compat_dir / "00-xray.conf"
    bash_compat.write_text(original, encoding="utf-8")
    compat_run = run_bash_tls(tls_fn, bash_compat_dir, bash_compat, "Reality", "on", "2", f)
    f.check(compat_run.returncode == 0, "Bash tls_type choice 2 rc=0",
            compat_run.stderr[:200])
    f.check(bash_compat.read_bytes() == compat_bytes,
            "Bash TLSv1.2+ output is byte-identical to Go",
            f"bash={sha256_bytes(bash_compat.read_bytes())} go={sha256_bytes(compat_bytes)}")

    bash_secure_dir = work / "bash-secure"
    bash_secure_dir.mkdir()
    bash_secure = bash_secure_dir / "00-xray.conf"
    bash_secure.write_text(original, encoding="utf-8")
    secure_run = run_bash_tls(tls_fn, bash_secure_dir, bash_secure, "Reality", "on", "1", f)
    f.check(secure_run.returncode == 0, "Bash tls_type choice 1 rc=0", secure_run.stderr[:200])
    f.check(bash_secure.read_bytes() == secure_bytes,
            "Bash TLSv1.3 output is byte-identical to Go",
            f"bash={sha256_bytes(bash_secure.read_bytes())} go={sha256_bytes(secure_bytes)}")
    observed["baseline"]["compatSha256"] = sha256_bytes(bash_compat.read_bytes())
    observed["baseline"]["secureSha256"] = sha256_bytes(bash_secure.read_bytes())

    # ---- S3: guards stay side-effect free ------------------------------
    guard_before = f.tree_digest(conf_dir)
    invalid = f.run([f.go, "--root", root, "xray", "tls", "--version", "9.9"])
    f.check(invalid.rc == 2, "invalid version exits 2", invalid.text[:160])
    missing = f.run([f.go, "--root", root, "xray", "tls"])
    f.check(missing.rc == 2, "missing --version exits 2", missing.text[:160])
    unknown = f.run([f.go, "--root", root, "xray", "tls", "--version", "1.3", "--bogus"])
    f.check(unknown.rc == 2, "unknown flag exits 2", unknown.text[:160])
    f.check(f.tree_digest(conf_dir) == guard_before,
            "rejected TLS commands leave the tree unchanged")

    # ---- S4: rollback on a broken nginx configuration -------------------
    main_before = conf.read_text(encoding="utf-8")
    write_text(conf, main_before + "bogus_directive on;\n")
    broken = f.run([f.go, "--root", root, "xray", "tls", "--version", "1.2+"])
    f.check(broken.rc == 1 and "was restored" in broken.text,
            "broken nginx makes the switch fail and restores", broken.text[:260])
    f.check(anchor_path.read_bytes() == secure_bytes,
            "failed switch leaves the previous TLS bytes in place")
    write_text(conf, main_before)
    retry = f.run([f.go, "--root", root, "xray", "tls", "--version", "1.2+"])
    f.check(retry.rc == 0, "restored nginx lets the same switch succeed", retry.text[:200])
    f.run([f.go, "--root", root, "xray", "tls", "--version", "1.3"])

    # ---- S5: TLS install accepts only 1.3 -------------------------------
    tls_root = seed_root(work / "tls-root", "TLS", "ws")
    tgen = f.run([f.go, "--root", tls_root, "xray", "generate", "--mode", "tls",
                  "--transport", "ws", "--domain", "example.com", "--port", "443",
                  "--uuid", "eeeeeeee-4444-4444-8444-444444444444",
                  "--out", tls_root / "config.json", "--nginx-out", work / "tls-server.conf",
                  "--fragments-out", tls_root / "fragments", "--json"])
    f.check(tgen.rc == 0, "generate TLS ws rc=0", tgen.text[:240])
    tls_conf_dir = tls_root / "etc/idleleo/conf/nginx"
    for item in (tls_root / "fragments").iterdir():
        target = tls_conf_dir / item.name
        target.write_text(rewrite_install_paths(item.read_text(encoding="utf-8"), tls_root),
                          encoding="utf-8")
    https_conf = tls_conf_dir / "03-xray-https.conf"
    write_text(https_conf, f"""server {{
    listen 9443 ssl;
    server_name example.com;
    ssl_certificate {cert};
    ssl_certificate_key {key};
    ssl_protocols         TLSv1.2 TLSv1.3;
    location / {{ return 204; }}
}}
""")
    write_text(tls_root / "usr/local/nginx/conf/nginx.conf", f"""load_module /usr/lib/nginx/modules/ngx_stream_module.so;
pid {tls_root}/usr/local/nginx/logs/nginx.pid;
error_log {tls_root}/usr/local/nginx/logs/error.log;
events {{}}
http {{
    include {tls_conf_dir}/02-xray-server.conf;
    include {tls_conf_dir}/03-xray-https.conf;
}}
""")
    tls_test = f.run([tls_root / "usr/local/nginx/sbin/nginx", "-t", "-p",
                      str(tls_root / "usr/local/nginx") + "/",
                      "-c", tls_root / "usr/local/nginx/conf/nginx.conf"])
    f.check(tls_test.rc == 0, "real nginx -t accepts the TLS install", tls_test.text[:300])
    tls_original = https_conf.read_text(encoding="utf-8")
    tls_compat = f.run([f.go, "--root", tls_root, "xray", "tls", "--version", "1.2+"])
    f.check(tls_compat.rc == 1 and "h3/quic" in tls_compat.text,
            "TLS install refuses TLSv1.2 (h3/quic)", tls_compat.text[:260])
    f.check(https_conf.read_text(encoding="utf-8") == tls_original,
            "refused TLSv1.2 leaves the server block untouched")
    tls_secure = f.run([f.go, "--root", tls_root, "xray", "tls", "--version", "1.3", "--json"])
    tls_secure_json = f.json_of(tls_secure, "tls 1.3 --json") if tls_secure.rc == 0 else None
    tls_bytes = https_conf.read_bytes()
    f.check(tls_secure.rc == 0 and b"ssl_protocols         TLSv1.3;" in tls_bytes,
            "TLS install pins ssl_protocols to TLSv1.3", tls_secure.text[:240])
    if tls_secure_json:
        f.check(tls_secure_json["mode"] == "TLS" and tls_secure_json["file"] == str(https_conf),
                "TLS json mode/file", json.dumps(tls_secure_json))
    observed["tls"]["refusalRc"] = tls_compat.rc
    observed["tls"]["secureSha256"] = sha256_bytes(tls_bytes)

    bash_tls_dir = work / "bash-tls"
    bash_tls_dir.mkdir()
    bash_tls = bash_tls_dir / "03-xray-https.conf"
    bash_tls.write_text(tls_original, encoding="utf-8")
    tls_run = run_bash_tls(tls_fn, bash_tls_dir, bash_tls, "TLS", "off", "2", f)
    f.check(tls_run.returncode == 0, "Bash tls_type TLS choice 2 rc=0", tls_run.stderr[:200])
    f.check(bash_tls.read_bytes() == tls_bytes,
            "Bash TLSv1.3 ssl_protocols line is byte-identical to Go",
            f"bash={sha256_bytes(bash_tls.read_bytes())} go={sha256_bytes(tls_bytes)}")

    # ---- S6: environment gates -----------------------------------------
    no_meta = work / "gate-no-metadata"
    write_text(no_meta / ".idleleo-phase01-sandbox", "I_ACCEPT_DISPOSABLE_SANDBOX\n")
    r = f.run([f.go, "--root", no_meta, "xray", "tls", "--version", "1.3"])
    f.check(r.rc == 3 and "缺少 manager metadata" in r.text,
            "root without metadata exits 3", r.text[:200])
    no_front = work / "gate-no-front"
    write_text(no_front / ".idleleo-phase01-sandbox", "I_ACCEPT_DISPOSABLE_SANDBOX\n")
    (no_front / "etc/idleleo/conf/nginx").mkdir(parents=True)
    write_text(no_front / "etc/idleleo/v1/metadata.json",
               json.dumps(metadata("Reality", "raw")) + "\n")
    r = f.run([f.go, "--root", no_front, "xray", "tls", "--version", "1.3"])
    f.check(r.rc == 1 and "not a managed Nginx front" in r.text,
            "root without a managed front exits 1", r.text[:220])
    one_mode = work / "gate-one-mode"
    write_text(one_mode / ".idleleo-phase01-sandbox", "I_ACCEPT_DISPOSABLE_SANDBOX\n")
    write_text(one_mode / "etc/idleleo/v1/metadata.json",
               json.dumps(metadata("None", "ws")) + "\n")
    r = f.run([f.go, "--root", one_mode, "xray", "tls", "--version", "1.3"])
    f.check(r.rc == 1 and "no managed Nginx TLS front" in r.text,
            "ws-only install exits 1", r.text[:220])

    compare["tls13Line"] = {
        "classification": "aligned",
        "goSha256": sha256_bytes(tls_bytes),
        "bashSha256": sha256_bytes(bash_tls.read_bytes()),
        "bytes": len(tls_bytes),
    }
    compare["realityTLS12"] = {
        "classification": "aligned",
        "goSha256": sha256_bytes(compat_bytes),
        "bashSha256": sha256_bytes(bash_compat.read_bytes()),
    }
    compare["realityTLS13"] = {
        "classification": "aligned",
        "goSha256": sha256_bytes(secure_bytes),
        "bashSha256": sha256_bytes(bash_secure.read_bytes()),
    }
    compare["tls12OnTLSMode"] = {
        "classification": "approved-difference",
        "go": "rc=1 with an explicit h3/quic explanation",
        "bash": "loops on choice 1 and only leaves the loop on choice 2",
    }
    compare["rollback"] = {
        "classification": "approved-difference",
        "go": "nginx -t failure or reload failure restores the previous bytes",
        "bash": "sed -i writes in place, restarts both services, no rollback",
    }
    compare["restartScope"] = {
        "classification": "approved-difference",
        "go": "reloads nginx only; a sandbox root skips and warns",
        "bash": "restarts nginx (when managed) and always restarts xray",
    }
    compare["discovery"] = {
        "classification": "new-go-behavior",
        "go": "locates ssl_protocols / $ssl_preread_protocol instead of editing a fixed path",
        "bash": "edits the global nginx_conf path",
    }

    f.write_json("observed.json", observed)
    f.write_json("baseline-compare.json", compare)
    shutil.rmtree(CERT_DIR, ignore_errors=True)


if __name__ == "__main__":
    sys.exit(run_fixture("F10", main))
